def run(code):
 ns={'__name__':'__main__'};buf=io.StringIO();old=os.getcwd();os.chdir(execdir)
 try:
  Path('main.py').write_text(code)
  with contextlib.redirect_stdout(buf):exec(compile(code,'main.py','exec'),ns)
 finally:sys.settrace(None);os.chdir(old)
 return ns,buf.getvalue().strip()
def test(kind,spec,i):return {'test_id':'t'+str(i),'kind':kind,'spec':spec,'visible':True,'message_on_fail':'Check the required computation and the named output; keep the supplied inputs.'}
def evaluated_test(code,expr,i):
 ns,_=run(code);old=os.getcwd();os.chdir(execdir)
 try:expected=normalized(eval(expr,ns))
 finally:sys.settrace(None);os.chdir(old)
 return test('value_equals',{'expr':expr,'expected':expected},i)
